R=Path(__file__).resolve().parent
sat=[]
for t in [0.01]+[i/2 for i in range(1,441)]:
 K=t+273.15;p=prop('P','T',K,'Q',0,'Water');sat.append(dict(T=t,p=p,uf=prop('U','T',K,'Q',0,'Water'),ug=prop('U','T',K,'Q',1,'Water'),hf=prop('H','T',K,'Q',0,'Water'),hg=prop('H','T',K,'Q',1,'Water'),vf=1/prop('D','T',K,'Q',0,'Water'),vg=1/prop('D','T',K,'Q',1,'Water')))
pressures=[.05,.1,.2,.5,1,1.2,2,3,4,5,6,8,10,12,15,20,25];superheats=[0,5,10,20,40,60,80,100,150,200];back=[.05,.1,.2,.5,1,1.2,1.5,2,3,5,10]
steam=[]
for pb in pressures:
 p=pb*1e5;ts=prop('T','P',p,'Q',1,'Water')-273.15;row=[]
 for sh in superheats:
  args=('P',p,'Q',1,'Water') if sh==0 else ('P',p,'T',ts+sh+273.15,'Water')
  h=prop('H',*args);s=prop('S',*args)
  row.append(dict(h=h,rho=prop('D',*args),dh=[max(0,h-prop('H','P',pe*1e5,'S',s,'Water')) if pe<pb else 0 for pe in back]))
 steam.append(dict(p=pb,Ts=ts,states=row))
liquid=[]
for t in range(0,100):liquid.append(dict(T=t,u=prop('U','P',1e5,'T',t+273.15,'Water'),h=prop('H','P',1e5,'T',t+273.15,'Water'),rho=prop('D','P',1e5,'T',t+273.15,'Water')))
base={'ENG':55,'STM':60,'BRN':13,'CND':32,'WTR':5,'RCV':7,'FUE':4,'ELE':3,'PMP':8.7,'MOTOR':7,'BOOST':2,'SEP':2,'MOUNTS':17,'SHIELD':8,'ADAPTER':3,'DUCTS':3}
entries=json.loads((R/'models/steam-internal-assembly.json').read_text())['entries'];routes=json.loads((R/'pipe-engineering.json').read_text())['routes'];routeby={r['id']:r for r in routes};mass=[]
for e in entries:
 id=e['id']
 if id in ['BODY','SUSP','GBX']:continue
 center=[(x+y)/2000 for x,y in zip(e['min_mm'],e['max_mm'])]
 if id in routeby:
  r=routeby[id];L=r['centerline_length_m'];od=r['od']/1000;di=(r.get('inside_id_mm') or 0)/1000
  if id.startswith('WIRE'):m=L*.25;reason='Условные 0,25 кг/м жгута; состав не выбран.'
  else:
   ri=od/2;ro=ri+r['insulation_mm']/1000;t=r['jacket_mm']/1000;inline=sum(math.dist(c['start_mm'],c['end_mm']) for c in r.get('inline_components',[]))/1000;bare=max(0,L-inline);ins=max(0,bare-2*r.get('exposed_end_mm',0)/1000);m=math.pi*(bare*(od**2-di**2)*7850/4+ins*((ro**2-ri**2)*150+((ro+t)**2-ro**2)*8000))
   reason='ρ трубы 7850, аэрогеля 150, кожуха 8000 кг/м³ — допущения; без массы клапанов, отводов, хомутов и новых соединительных муфт. Учитываются открытые окончания и разрывы под фильтр/насос; масса арматуры ещё неизвестна.'
 else:m=base[id];reason='Оценка для исследования, не паспорт и не взвешивание.'
 if id=='PIPE_FLUE':m+=3;reason+=' Плюс 3 кг дымосос/кронштейны — гипотеза.'
 if id=='PMP':reason='8,7 кг по паспорту Cat 5CP2120W; центр габарита CAD, дополнительные штуцеры и привод отдельно.'

 mass.append(dict(id=id,name=e.get('name',id),kg=round(m,4),xyz_m=center,source=reason))
roles={
 'ENG':('Пар давит на поршни; золотники подают и выпускают пар. Шатуны преобразуют движение в вращение.','Работа расширения; первый закон термодинамики и момент сил.','Pᵢ = ṁ ηᵢₛ (h₁ − h₂ₛ); τ = P/ω','Рабочий объём, фазы клапанов и карта расхода пока являются гипотезами.'),
 'STM':('Вода получает тепло от сгорания топлива, кипит и перегревается.','Сохранение массы и энергии; фазовое равновесие воды IAPWS-95.','dM/dt = ṁвх − ṁвых; dU/dt = Q + ṁвх hвх − ṁвых hвых','Модель сосредоточенная: реальный змеевик требует распределённого расчёта, прочности и проверки сухого хода.'),
 'BRN':('Передаёт энергию выбранного источника генератору; топливо и инерция различаются.','Химическая энергия и теплопередача.','Q̇ = ηкотла ṁтопл Hᵤ','Дизельный ориентир G10 54–120 кВт; остальные компактные источники — прототипы. КПД и карта нагрузки требуют испытаний.'),
 'CND':('Отводит теплоту отработанного пара, переводит его в жидкую воду.','Тепловой баланс, конденсация, теплопроводность и конвекция.','Q̇ = UA(T − Tвозд); Q̇ ≤ ρвозд cₚ V̇возд ΔT','UA и характеристики вентиляторов не выбраны; давление меняется вслед за накоплением энергии.'),
 'WTR':('Хранит холодную воду для восполнения потерь.','Сохранение массы; гидростатическое давление.','Δp = ρ g Δz; dM/dt = −ṁподп','Прозрачная вода окрашена слабым голубым только для различения контуров.'),
 'RCV':('Собирает горячий конденсат и подпитку перед питательным насосом.','Смешение потоков и энергетический баланс.','dU/dt = Σṁhвх − ṁhвых − Q̇потерь','Закрытый приёмник при 2 бар abs — гипотеза регулируемой газовой подушки, не рассчитанный сосуд.'),
 'PMP':('Повышает давление воды для подачи в генератор.','Гидравлическая работа, объёмная подача и кавитационный запас.','Pнас = Δp V̇ / ηнас; V̇ = n Vраб ηоб','Температурный предел кандидата 82 °C; реальный NPSH, привод и соединения ещё не проверены.'),
 'BOOST':('Создаёт подпор перед горячим питательным насосом; фильтр задерживает загрязнения.','Бернулли с потерями и условие отсутствия кавитации.','NPSHₐ = (pвх − pнас.пара)/(ρg) + v²/(2g)','Для допуска нужен NPSHᵣ конкретного насоса; он не выдумывается.'),
 'FUE':('Хранит топливо или батарею выбранного варианта отдельно от горячей и пассажирской зон.','Массовый баланс и теплота сгорания.','dMтопл/dt = −Q̇топл/Hᵤ','Дизель в визуализации светло-жёлтый; фактический оттенок зависит от партии.'),
 'ELE':('Управляет подачей воды и топлива, собирает показания; защита должна действовать независимо.','Обратная связь, электрическая мощность, причинность защит.','P = UI; ошибка регулирования e = заданное − измеренное','Кнопки сайта не являются схемой управления или пусковой инструкцией для оборудования.'),
 'MOTOR':('Вращает плунжерный насос через передачу.','Электромеханическое преобразование и баланс момента.','J dω/dt = Στ; P = τω','Реальный электродвигатель и источник питания не выбраны.'),
 'SEP':('Принимает условный сброс; отделяет капельную фазу только при разработанной конструкции.','Сохранение массы и энергии двухфазного потока.','ṁсброса ≥ ṁпарогенерации — необходимое, но не достаточное условие','Геометрия и пропускная способность аварийного сброса не рассчитаны; имитация не подбирает клапан.'),
 'GBX':('Передаёт момент к главной передаче и колёсам.','Передаточные отношения и сохранение мощности с потерями.','nдв = nкол iКПП iглав iадапт; τкол = η i τдв','Радиус качения 0,28 м взят из расчётного допущения, не из игровой шины.'),
 'ADAPTER':('Согласует оси и обороты паровой машины с КПП.','Кинематика, момент и соосность.','i = ωвх/ωвых; Pвых = ηPвх','Адаптер 0,73 в симуляции — гипотеза, не готовая конструкция.'),
 'MOUNTS':('Передают массу, момент и вибрацию агрегатов на силовые точки кузова.','Равновесие сил и моментов, напряжения, усталость.','ΣF = ma; ΣM = Iα; σ = F/A','Контакт с игровым полом не подтверждает силовую точку или прочность.'),
 'SHIELD':('Отделяет горячие поверхности и возможные утечки от пассажиров и топлива.','Теплопроводность, конвекция и излучение.','Q̇ = λAΔT/δ; Q̇изл = εσA(T₁⁴ − T₂⁴)','Пожарная стойкость и герметичность не определяются цветом или нарисованной плоскостью.'),
 'DUCTS':('Направляют охлаждающий воздух через конденсаторы к штатным отверстиям.','Неразрывность потока и аэродинамическое сопротивление.','v = V̇/Aсв; Pвент = Δp V̇/η','Внутренние отверстия и кривые вентиляторов не измерены.'),
 'BODY':('Несущий кузов удерживает оборудование, защищает пассажиров и задаёт доступный объём.','Равновесие, деформация и прочность конструкции.','ΣF = 0; ΣM = 0; δ ∝ F/(EI)','Это игровая сетка; её габарит не доказывает реальную свободную полость.'),
 'SUSP':('Рычаги направляют движение колёс; торсионы/пружины несут нагрузку, амортизаторы гасят колебания.','Законы Ньютона, виртуальная работа, упругость и демпфирование.','kкол = kпруж λ²; Fпруж = Fкол/λ; Fдемп = c v','Ход, жёсткости, преднатяги и шарниры требуют измерений. Реакции всех сайлент-блоков без них не определены.')}
nodes={}
for e in entries:
 id=e['id'];r=routeby.get(id)
 if r:
  if id.startswith('WIRE'):role=('Передаёт электрическое питание и сигналы датчиков.','Закон Ома, токовая нагрузка и падение напряжения.','ΔU = IρL/A','Жгут не является жидкостью; анимация потока для него отключена.')
  elif id=='PIPE_FLUE':role=('Соединяет выход генератора с задним выпуском через изолированный газовый канал и условный дымосос.','Газодинамика и теплопередача через стенку/изоляцию.','v = ṁ/(ρA); Q̇/L = ΔT / (Rизоляции + Rнаруж)','Дизель: расчёт ID80 для источника до 120 кВт. Дрова/пеллеты: ID100 с более толстой изоляцией. Окно кузова, камера и карта дымососа не подтверждены.')
  else:role=('Соединяет '+r['ends'][0]+' с '+r['ends'][-1]+': переносит '+('пар' if r['fluid'] in ['steam','exhaust'] else 'топливо' if r['fluid']=='fuel' else 'воду')+'.','Сохранение массы, Бернулли с потерями, тепловой баланс.','v = ṁ/(ρA); Δp = (fL/D + ΣK)ρv²/2','ID/OD и изгибы посчитаны; прочность, компенсация расширения и фитинги не выбраны.')
 else:role=roles[id]
 nodes[id]=dict(name=e.get('name',{'BRN':'Компактный дизель · ориентир G10','PMP':'Cat Pumps','BODY':'Кузов ЗАЗ-968М','SUSP':'Штатная подвеска'}.get(id,id)),description=role[0],law=role[1],formula=role[2],limit=role[3])
