for owner,path in [('SUSP','models/stock-suspension.glb'),('BODY','models/zaz-968m-yatloo.glb')]:
 b=(R/path).read_bytes();n=struct.unpack_from('<I',b,12)[0];glb=json.loads(b[20:20+n])
 for node in glb['nodes']:
  if 'mesh' not in node:continue
  name=node.get('name','');low=name.lower();role=roles[owner]
  if owner=='SUSP':
   if 'пружина' in low:role=('Упруго поддерживает нагрузку на колесо и запасает энергию при ходе подвески.','Закон Гука и виртуальная работа рычага.','F = kδ; E = kδ²/2; kкол = kпруж λ²','Жёсткость, преднатяг и допустимый ход этой пружины не измерены.')
   elif 'амортизатор' in low:role=('Рассеивает энергию колебаний подвески за счёт сопротивления протеканию жидкости.','Демпфирование и преобразование механической энергии в тепло.','F ≈ cv; Pтепла = Fv','Реальные характеристики сжатия/отбоя нелинейны и не заданы.')
   elif 'торсион' in low:role=('Скручивается при ходе переднего рычага и создаёт возвращающий момент.','Упругое кручение.','M = (GJ/L)θ; kкол = kθ/l²','Размеры пластин, условия контакта и жёсткость пакета требуют измерений.')
   elif 'сайлент' in low or 'шарнир' in low:role=('Соединяет рычаг с опорой, допускает поворот и передаёт силы; упругая втулка влияет на кинематику.','Равновесие сил/моментов и упругость соединения.','ΣF = 0; ΣM = 0; Fвтулки = Kδ','Матрица жёсткости втулки и реакции шарниров не определены.')
   elif 'полуось' in low or 'пыльник' in low:role=('Полуось передаёт момент от дифференциала к колесу при перемещении подвески; пыльник защищает соединение.','Кинематика кардана, кручение и изгиб.','P = Mω; θкруч = ML/(GJ)','Углы, допустимый ход и прочность полуоси должны быть проверены.')
   elif 'барабан' in low or 'ступица' in low:role=('Ступица поддерживает колесо на подшипниках; барабан воспринимает тормозной момент.','Радиальные/осевые реакции, трение и момент торможения.','Mторм ≈ μNr; Pтепла = Mторм ω','Грузоподъёмность подшипников и тепловая проверка тормозов отсутствуют.')
   elif 'рычаг' in low:role=('Направляет движение колеса вокруг шарниров и передаёт усилия к пружине и кузову.','Равновесие рычага и виртуальная работа.','Fкол dz = Fпруж ds; λ = ds/dz','Для реальных сил нужны координаты шарниров, λ по ходу, нагрузки и свойства втулок.')
   elif 'кронштейн' in low or 'опора' in low:role=('Передаёт реакции подвески на кузов в местах крепления.','Статика, контактные напряжения и усталость.','ΣF = 0; ΣM = 0; σ = F/A','Крепления и силовые точки исходной игровой сеткой не подтверждены.')
