manifest=dict(status='Сосредоточенная нестационарная исследовательская модель; не цифровой двойник выбранного оборудования',coolprop_version=CoolProp.__version__,units='SI; давление всегда абсолютное',sources=[dict(title='CoolProp / IAPWS-95: вода и пар',url='https://coolprop.org/fluid_properties/fluids/Water.html'),dict(title='Spirax Sarco: прогрев и дренирование паропроводов',url='https://www.spiraxsarco.com/learn-about-steam/steam-distribution/steam-mains-and-drainage'),dict(title='ЗАЗ-968М: штатная подвеска и передача',url='https://djvu.online/file/yS7dQhMxx1lMm')],defaults=dict(ambient_C=20,boiler_volume_m3=.012,condenser_volume_m3=.020,boiler_charge_kg=2,condenser_charge_kg=.5,receiver_charge_kg=17.5,makeup_kg=31.7,fuel_kg=17.8*.835,boiler_capacity_J_K=45*450,superheater_capacity_J_K=15*450,condenser_capacity_J_K=30*500,receiver_capacity_J_K=7*500,engine_capacity_J_K=55*450,boiler_efficiency=.85,boiler_loss_W_K=15,superheater_fraction=.12,superheater_UA_W_K=600,condenser_UA_W_K=2000,airflow_m3_s=1.0829,air_area_m2=2*.5*.085*.65,engine_bore_m=.1,engine_stroke_m=.12,cylinders=2,acting_sides=2,admission=.30,volumetric_efficiency=.85,isentropic_efficiency=.5,mechanical_efficiency=.9,inertia_kg_m2=1.2,adapter=.73,target_p_bar_abs=10,target_T_C=250,study_limit_p_bar_abs=12,study_limit_condenser_bar_abs=3,study_limit_superheater_C=350,study_limit_rpm=2600,return_fraction=.999,vent_recovery_fraction=.995,diesel_LHV_J_kg=42.6e6),limitations=['Объёмы, теплоёмкости, UA, рабочий объём, фазы и инерция — открытые гипотезы, не паспортные характеристики.','Вода в генераторе/конденсаторе считается равновесной двухфазной смесью с одним T; перегреватель и двигатель — отдельные тепловые узлы.','Неконденсируемый воздух учитывается как идеальный газ и удаляется только при перепаде давления.','Показываются средние температуры узлов, не пространственное CFD/FEM поле; локальная температура металла не рассчитана.','Исследовательские пределы 12/3 бар, 350 °C и 2600 об/мин не являются MAWP, уставками сертифицированной защиты или паспортными пределами.','Симуляция не подтверждает горение, прочность котла, арматуру, управление, монтаж, подвеску и допуск к дорогам.'],masses=mass,nodes=nodes,subnodes=subnodes,water=dict(saturation=sat,liquid=liquid,pressures_bar=pressures,superheats_C=superheats,back_bar=back,steam=steam))
